CREATE OR REPLACE TRIGGER trg_generar_id_jugada
BEFORE INSERT ON JUGADA
FOR EACH ROW
DECLARE
    v_max_id NUMBER;
BEGIN
    -- Si el usuario no proporcionó ID_jugada, se calcula
    IF :NEW.ID_jugada IS NULL THEN
        SELECT NVL(MAX(ID_jugada), 0) + 1
          INTO v_max_id
          FROM JUGADA
         WHERE ID_juego = :NEW.ID_juego
           FOR UPDATE;

        :NEW.ID_jugada := v_max_id;
    END IF;
END;
/

-- Bastaba con poner "ID_jugada NUMBER(20) GENERATED BY DEFAULT AS IDENTITY NOT NULL"
-- este no lo puse en trg_jugada, en cambio, cambié el esquema (puse el alter)
